#!/usr/bin/env bash
set -euo pipefail

# Build/verification imports must not write generated bytecode into source.
export PYTHONDONTWRITEBYTECODE=1
export GOENV=off
export GOFLAGS=
build_dir=$(cd "$(dirname "$0")" && pwd)
repo=$(cd "$build_dir/../../.." && pwd)
root="$repo/code"
inputs="$build_dir/inputs.json"
manifest="$build_dir/public-source-v1.json"
target=${1:-darwin_arm64}
case "$target" in darwin_amd64) arch=amd64;; darwin_arm64) arch=arm64;; *) echo "target must be darwin_amd64 or darwin_arm64" >&2; exit 2;; esac
output_root=${REPLICARO_UNSIGNED_OUT:-$build_dir/out/$target}
[[ "$output_root" == /* ]] || output_root="$PWD/$output_root"
[[ ! -e "$output_root" && ! -L "$output_root" ]] || { echo "refusing to reuse unsigned output root: $output_root" >&2; exit 2; }
build_root="$output_root/work"
release_root="$output_root/release"
[[ "${REPLICARO_SIGNED_BUILD:-0}" == 0 && "${REPLICARO_INTERNAL_ADHOC:-0}" == 0 ]] || { echo "This public builder only creates unsigned outputs." >&2; exit 2; }
(cd "$root/backend" && go run -mod=readonly ./tools/targetverify --target "$target")
bash "$build_dir/verify-toolchains.sh" "$target"
source_identity=$(cd "$build_dir" && go run ./cmd/contract source --root "$repo" --manifest "$manifest")
version=$(cd "$build_dir" && go run ./cmd/contract inputs --file "$inputs" --field version)
build_timestamp=${REPLICARO_BUILD_TIMESTAMP:-}
source_date_epoch=$(cd "$build_dir" && go run ./cmd/contract timestamp --value "$build_timestamp")
[[ "$(node -p 'require(process.argv[1]).version' "$root/frontend/package.json")" == "$version" ]] || { echo "frontend version differs from unsigned build inputs" >&2; exit 2; }
(cd "$root/backend" && go run ./tools/webuiembed -preflight-root "$build_root" -frontend-output "$build_root/frontend/dist")
mkdir -p "$build_root" "$release_root"
# shellcheck source=code/build/unsigned/compile-macos.sh
source "$build_dir/compile-macos.sh" helper
# shellcheck source=code/build/unsigned/compile-macos.sh
source "$build_dir/compile-macos.sh" application
macos_icon_source="$root/backend/desktop/assets/packaging/replicaro-app-icon-teal-on-white-1024.png"
iconset="$build_root/Replicaro.iconset"
macos_icon="$build_root/Replicaro.icns"
rm -rf "$iconset"
rm -f "$macos_icon"
mkdir -p "$iconset"
while read -r filename pixels; do
  sips -z "$pixels" "$pixels" "$macos_icon_source" --out "$iconset/$filename" >/dev/null
done <<'ICON_SIZES'
icon_16x16.png 16
icon_16x16@2x.png 32
icon_32x32.png 32
icon_32x32@2x.png 64
icon_128x128.png 128
icon_128x128@2x.png 256
icon_256x256.png 256
icon_256x256@2x.png 512
icon_512x512.png 512
icon_512x512@2x.png 1024
ICON_SIZES
iconutil -c icns "$iconset" -o "$macos_icon"
rm -rf "$iconset"
app="$build_root/Replicaro-$target.app"; rm -rf "$app"; mkdir -p "$app/Contents/MacOS" "$app/Contents/Resources" "$build_root/provenance"
cp "$build_root/Replicaro-$target" "$app/Contents/MacOS/Replicaro"
cp "$root/backend/engines/metadata.json" "$build_root/provenance/engines-metadata.json"
cp "$root/backend/rclone/assets/metadata.json" "$build_root/provenance/rclone-metadata.json"
cp "$root/backend/integrations/catalog.json" "$build_root/provenance/integrations-catalog.json"
python3 "$build_dir/write-licenses.py" --platform macos --output "$app/Contents/Resources/LICENSES.txt"
cp "$root/backend/desktop/assets/replicaro-favicon.png" "$app/Contents/Resources/replicaro-favicon.png"
cp "$macos_icon" "$app/Contents/Resources/Replicaro.icns"
signed_json=false
executable_sha256=$(shasum -a 256 "$build_root/Replicaro-$target" | awk '{print $1}')
printf '{"schema":"replicaro-product-provenance-v2","target":"%s","version":"%s","buildTimestamp":"%s","source":"https://github.com/replicaro/replicaro","sourceIdentity":"%s","standaloneExecutableSha256":"sha256:%s","signed":%s}\n' "$target" "$version" "$build_timestamp" "$source_identity" "$executable_sha256" "$signed_json" > "$build_root/provenance/product-provenance.json"
printf '{"target":"%s","version":"%s","buildTimestamp":"%s","bundleIdentifier":"io.replicaro.desktop","nativeDesktop":true,"storageHelper":"embedded","storageHelperTarget":"%s","publicFormats":["dmg","app.zip"],"signed":%s,"notarized":%s,"frontend":"embedded","licenses":"Contents/Resources/LICENSES.txt"}\n' "$target" "$version" "$build_timestamp" "$target" "$signed_json" "$signed_json" > "$build_root/provenance/manifest.json"
bash "$build_dir/sbom.sh" "$target" "$build_root/provenance/sbom.cdx.json"
cat > "$app/Contents/Info.plist" <<PLIST
<?xml version="1.0" encoding="UTF-8"?><plist version="1.0"><dict><key>CFBundleIdentifier</key><string>io.replicaro.desktop</string><key>CFBundleName</key><string>Replicaro</string><key>CFBundleDisplayName</key><string>Replicaro</string><key>CFBundleExecutable</key><string>Replicaro</string><key>CFBundlePackageType</key><string>APPL</string><key>CFBundleShortVersionString</key><string>$version</string><key>CFBundleVersion</key><string>$version</string><key>CFBundleIconFile</key><string>Replicaro.icns</string><key>CFBundleGetInfoString</key><string>Replicaro.com</string><key>LSMinimumSystemVersion</key><string>11.0</string><key>LSUIElement</key><true/><key>NSHighResolutionCapable</key><true/></dict></plist>
PLIST
chmod 700 "$app/Contents/MacOS/Replicaro"
python3 - "$app" "$source_date_epoch" <<'PY'
import os, sys
root, epoch = sys.argv[1], int(sys.argv[2])
for directory, directories, files in os.walk(root, topdown=False, followlinks=False):
    for name in files:
        os.utime(os.path.join(directory, name), (epoch, epoch), follow_symlinks=False)
    for name in directories:
        os.utime(os.path.join(directory, name), (epoch, epoch), follow_symlinks=False)
    os.utime(directory, (epoch, epoch), follow_symlinks=False)
PY
portable_archive="$build_root/Replicaro-$version-$target-portable.zip"
dmg="$build_root/Replicaro-$version-$target.dmg"
for output in "$portable_archive" "$portable_archive.sha256" "$dmg" "$dmg.sha256"; do
  [[ ! -e "$output" ]] || { echo "refusing to replace macOS distribution output: $output" >&2; exit 2; }
done
distribution_stage=$(mktemp -d "$build_root/macos-distribution-stage.XXXXXX")
cleanup_distribution_stage() {
  [[ ! -d "$distribution_stage" ]] || rm -R "$distribution_stage"
}
trap cleanup_distribution_stage EXIT

portable_stage="$distribution_stage/portable"
dmg_stage="$distribution_stage/dmg"
mkdir "$portable_stage" "$dmg_stage"
ditto "$app" "$portable_stage/Replicaro.app"
ditto "$app" "$dmg_stage/Replicaro.app"
ln -s /Applications "$dmg_stage/Applications"
(cd "$portable_stage" && find Replicaro.app -print | LC_ALL=C sort | TZ=UTC zip -X -y -q "$portable_archive" -@)
create_dmg() {
  local attempt candidate status=1
  for attempt in 1 2; do
    candidate="$distribution_stage/Replicaro-$version-$target-attempt-$attempt.dmg"
    echo "Creating macOS DMG (attempt $attempt of 2)..."
    if hdiutil create -ov -format UDZO -volname Replicaro -srcfolder "$dmg_stage" "$candidate"; then
      [[ -f "$candidate" && ! -L "$candidate" ]] || { echo "hdiutil did not create an ordinary DMG file" >&2; return 1; }
      mv -- "$candidate" "$dmg"
      return 0
    else
      status=$?
      echo "macOS DMG creation attempt $attempt of 2 failed with exit code $status." >&2
    fi
    [[ "$attempt" == 2 ]] || sleep 2
  done
  return "$status"
}
create_dmg
cleanup_distribution_stage
trap - EXIT
cp "$portable_archive" "$dmg" "$release_root/"
(cd "$build_dir" && go run ./cmd/contract write --root "$release_root" --inputs "$inputs" --target "$target" --source-identity "$source_identity" --build-timestamp "$build_timestamp")
echo "Unsigned macOS DMG and portable ZIP created in $release_root."
